examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true }, variant = MonarchButtonVariant.Danger)
if (open) {
    MonarchDialog(
        onDismissRequest = { open = false },
        title = {{title}},
        description = {{description}},
        closeButton = true,
        actions = {
            MonarchButton(text = {{cancel}}, onClick = { open = false })
            MonarchButton(text = {{confirm}}, onClick = { open = false }, variant = MonarchButtonVariant.Danger)
        },
        content = {
            MonarchText(text = {{body}})
        },
    )
}

examples.code:
MonarchButton(text = "Delete project", onClick = { open = true }, variant = MonarchButtonVariant.Danger)
if (open) {
    MonarchDialog(
        onDismissRequest = { open = false },
        title = "Delete project?",
        description = "This removes all tasks and sprints. It cannot be undone.",
        closeButton = true,
        actions = {
            MonarchButton(text = "Cancel", onClick = { open = false })
            MonarchButton(text = "Delete", onClick = { open = false }, variant = MonarchButtonVariant.Danger)
        },
        content = {
            MonarchText(text = "Type the project name to confirm.")
        },
    )
}

MonarchButton(text = "Export", onClick = { open = true })
if (open) {
    MonarchDialog(
        onDismissRequest = { open = false },
        title = "Export started",
        description = "We will email you a link when the file is ready.",
        actions = {
            MonarchButton(text = "OK", onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        },
    )
}

if (open) {
    MonarchDialog(
        onDismissRequest = { open = false },
        title = "Rename report",
        // A stray tap outside does not lose the typed name; back still closes it.
        dismissOnClickOutside = false,
        actions = {
            MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(text = "Save", onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        },
    ) {
        MonarchTextField(value = name, onValueChange = { name = it }, label = "Name")
    }
}

if (open) {
    Dialog(
        onDismissRequest = { open = false },
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        Scaffold(
            topBar = {
                TopAppBar(
                    title = { Text("New invoice") },
                    navigationIcon = {
                        MonarchButton(text = "Cancel", onClick = { open = false }, variant = MonarchButtonVariant.Ghost)
                    },
                    actions = {
                        MonarchButton(text = "Save", onClick = { open = false }, variant = MonarchButtonVariant.Primary)
                    },
                )
            },
        ) { padding ->
            Column(modifier = Modifier.padding(padding).padding(MonarchTheme.spacing.space4)) {
                MonarchTextField(value = amount, onValueChange = { amount = it }, label = "Amount")
            }
        }
    }
}
